export interface Post {
  title: string;
  date: string;
  tags: string[];
  draft: boolean;
  slug: string;
  content: string;
  excerpt: string;
}

export interface SiteConfig {
  title: string;
  description: string;
  url: string;
  author: string;
}

export interface BuildContext {
  posts: Post[];
  tags: Map<string, Post[]>;
  config: SiteConfig;
}

export interface TemplateData {
  site: SiteConfig;
  posts: Post[];
  post?: Post;
  tags?: { name: string; posts: Post[] }[];
}

import fs from "node:fs";
import path from "node:path";
import matter from "gray-matter";

export interface FrontmatterInput {
  title?: string;
  date?: string;
  tags?: string | string[];
  draft?: boolean;
}

export function parseFrontmatter(
  filePath: string
): { frontmatter: FrontmatterInput; content: string } | null {
  const raw = fs.readFileSync(filePath, "utf-8");
  const parsed = matter(raw);
  const fm = parsed.data as FrontmatterInput;

  return {
    frontmatter: {
      title: fm.title ?? path.basename(filePath, ".md"),
      date: fm.date ?? new Date().toISOString().split("T")[0],
      tags: normalizeTags(fm.tags),
      draft: fm.draft === true || fm.draft === "true",
    },
    content: parsed.content,
  };
}

function normalizeTags(tags: string | string[] | undefined): string[] {
  if (!tags) return [];
  if (Array.isArray(tags)) return tags.filter(Boolean);
  return tags
    .split(",")
    .map((t) => t.trim())
    .filter(Boolean);
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code, lang) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return code;
    },
  })
);

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown) as string;
}

import fs from "node:fs";
import path from "node:path";
import Handlebars from "handlebars";
import { TemplateData } from "./types";

let partialsDir = "";

export function registerPartials(dir: string): void {
  partialsDir = dir;
  if (!fs.existsSync(dir)) return;
  for (const file of fs.readdirSync(dir)) {
    if (file.endsWith(".hbs")) {
      const name = path.basename(file, ".hbs");
      const source = fs.readFileSync(path.join(dir, file), "utf-8");
      Handlebars.registerPartial(name, source);
    }
  }
}

export function renderTemplate(
  templateDir: string,
  layout: string,
  data: TemplateData
): string {
  const layoutPath = path.join(templateDir, `${layout}.hbs`);
  const layoutSource = fs.readFileSync(layoutPath, "utf-8");

  registerPartials(path.join(templateDir, "partials"));

  const compiled = Handlebars.compile(layoutSource);
  return compiled(data);
}

import { Post, TemplateData } from "./types";

export function buildTagIndex(posts: Post[]): Map<string, Post[]> {
  const index = new Map<string, Post[]>();
  for (const post of posts) {
    for (const tag of post.tags) {
      const existing = index.get(tag) ?? [];
      existing.push(post);
      index.set(tag, existing);
    }
  }
  for (const [, taggedPosts] of index) {
    taggedPosts.sort((a, b) => b.date.localeCompare(a.date));
  }
  return index;
}

export function tagsTemplateData(
  tagIndex: Map<string, Post[]>
): { name: string; posts: Post[] }[] {
  return Array.from(tagIndex.entries()).map(([name, posts]) => ({
    name,
    posts,
  }));
}

import { Post, SiteConfig } from "./types";

export interface RssItem {
  title: string;
  description: string;
  url: string;
  date: string;
}

export function generateRssXml(
  config: SiteConfig,
  posts: Post[]
): string {
  const items = posts.map((p) => rssItem(config, p));
  return [
    `<?xml version="1.0" encoding="utf-8"?>`,
    `<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">`,
    `<channel>`,
    `<title>${escapeXml(config.title)}</title>`,
    `<link>${escapeXml(config.url)}</link>`,
    `<description>${escapeXml(config.description)}</description>`,
    `<atom:link href="${escapeXml(config.url)}/feed.xml" rel="self" type="application/rss+xml"/>`,
    ...items.map((item) => [
      `<item>`,
      `<title>${escapeXml(item.title)}</title>`,
      `<link>${escapeXml(item.url)}</link>`,
      `<description>${escapeXml(item.description)}</description>`,
      `<pubDate>${new Date(item.date).toUTCString()}</pubDate>`,
      `<guid>${escapeXml(item.url)}</guid>`,
      `</item>`,
    ].join("\n")),
    `</channel>`,
    `</rss>`,
  ].join("\n");
}

function rssItem(config: SiteConfig, post: Post): RssItem {
  return {
    title: post.title,
    description: post.excerpt,
    url: `${config.url}/${post.slug}.html`,
    date: post.date,
  };
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import http from "node:http";
import fs from "node:fs";
import path from "node:path";
import { WebSocketServer, WebSocket } from "ws";

const RELOAD_SCRIPT = `<script>
(function(){
  var ws = new WebSocket('ws://' + location.host + '/__reload__');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() { setTimeout(function(){location.reload()}, 1000); };
})();
</script>`;

export function startDevServer(
  outputDir: string,
  port: number,
  onRebuild: () => void
): { wss: WebSocketServer; server: http.Server } {
  const mimeTypes: Record<string, string> = {
    ".html": "text/html",
    ".css": "text/css",
    ".js": "application/javascript",
    ".json": "application/json",
    ".xml": "application/xml",
    ".png": "image/png",
    ".jpg": "image/jpeg",
    ".svg": "image/svg+xml",
  };

  const server = http.createServer((req, res) => {
    const url = req.url ?? "/";
    let filePath = path.join(outputDir, url === "/" ? "index.html" : url);

    if (!path.extname(filePath)) {
      filePath += ".html";
    }

    const ext = path.extname(filePath);
    const contentType = mimeTypes[ext] ?? "application/octet-stream";

    try {
      let content = fs.readFileSync(filePath);

      if (ext === ".html" || ext === "") {
        content = Buffer.from(
          content
            .toString("utf-8")
            .replace("</body>", `${RELOAD_SCRIPT}</body>`)
        );
      }

      res.writeHead(200, { "Content-Type": contentType });
      res.end(content);
    } catch {
      res.writeHead(404);
      res.end("Not found");
    }
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws) => {
    ws.on("message", () => {});
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });

  return { wss, server };
}

export function reloadClients(wss: WebSocketServer): void {
  for (const client of wss.clients) {
    if (client.readyState === WebSocket.OPEN) {
      client.send("reload");
    }
  }
}

import fs from "node:fs";
import path from "node:path";
import { parseFrontmatter } from "./frontmatter";
import { renderTemplate } from "./render";
import { markdownToHtml } from "./highlight";
import { buildTagIndex, tagsTemplateData } from "./tags";
import { generateRssXml } from "./rss";
import { Post, SiteConfig, TemplateData } from "./types";

export interface BuildOptions {
  sourceDir: string;
  templateDir: string;
  outputDir: string;
  config: SiteConfig;
}

export function build(options: BuildOptions): number {
  const { sourceDir, templateDir, outputDir, config } = options;

  fs.mkdirSync(outputDir, { recursive: true });

  const posts = loadPosts(sourceDir);
  const published = posts.filter((p) => !p.draft);
  published.sort((a, b) => b.date.localeCompare(a.date));

  const tagIndex = buildTagIndex(published);
  const tags = tagsTemplateData(tagIndex);

  const baseData: TemplateData = {
    site: config,
    posts: published,
    tags,
  };

  const indexHtml = renderTemplate(templateDir, "index", baseData);
  fs.writeFileSync(path.join(outputDir, "index.html"), indexHtml);

  fs.mkdirSync(path.join(outputDir, "tags"), { recursive: true });
  for (const tag of tags) {
    const tagData: TemplateData = {
      site: config,
      posts: tag.posts,
      tags,
    };
    const html = renderTemplate(templateDir, "tag", tagData);
    fs.mkdirSync(path.join(outputDir, "tags", tag.name), { recursive: true });
    fs.writeFileSync(
      path.join(outputDir, "tags", tag.name, "index.html"),
      html
    );
  }

  const tagsIndexHtml = renderTemplate(templateDir, "tags-index", baseData);
  fs.writeFileSync(path.join(outputDir, "tags", "index.html"), tagsIndexHtml);

  fs.mkdirSync(path.join(outputDir, "posts"), { recursive: true });
  for (const post of published) {
    const htmlContent = markdownToHtml(post.content);
    const postData: TemplateData = {
      site: config,
      posts: published,
      post: { ...post, content: htmlContent },
      tags,
    };
    const html = renderTemplate(templateDir, "post", postData);
    fs.mkdirSync(path.join(outputDir, "posts", post.slug), { recursive: true });
    fs.writeFileSync(
      path.join(outputDir, "posts", post.slug, "index.html"),
      html
    );
  }

  const rssXml = generateRssXml(config, published);
  fs.writeFileSync(path.join(outputDir, "feed.xml"), rssXml);

  fs.writeFileSync(
    path.join(outputDir, "site.json"),
    JSON.stringify(config, null, 2)
  );

  return published.length;
}

function loadPosts(dir: string): Post[] {
  const posts: Post[] = [];
  for (const file of fs.readdirSync(dir)) {
    if (!file.endsWith(".md")) continue;
    const filePath = path.join(dir, file);
    const parsed = parseFrontmatter(filePath);
    if (!parsed) continue;
    const { frontmatter, content } = parsed;
    posts.push({
      title: frontmatter.title ?? "Untitled",
      date: frontmatter.date ?? new Date().toISOString().split("T")[0],
      tags: frontmatter.tags ?? [],
      draft: frontmatter.draft ?? false,
      slug: path.basename(file, ".md"),
      content,
      excerpt: content.slice(0, 200).replace(/\n/g, " "),
    });
  }
  return posts;
}

import { Command } from "commander";
import chokidar from "chokidar";
import path from "node:path";
import { build, BuildOptions } from "./build";
import { startDevServer, reloadClients } from "./server";

export function runCli(args: string[]): void {
  const program = new Command();

  program
    .name("statik")
    .description("Static site generator")
    .option("-s, --source <dir>", "Source directory of Markdown files", "content")
    .option("-t, --templates <dir>", "Template directory of Handlebars files", "templates")
    .option("-o, --output <dir>", "Output directory for generated HTML", "dist")
    .option("--title <title>", "Site title", "My Site")
    .option("--description <desc>", "Site description", "")
    .option("--url <url>", "Site URL", "http://localhost:3000")
    .option("--author <author>", "Site author", "")
    .option("--serve", "Start dev server", false)
    .option("-p, --port <port>", "Dev server port", "3000")
    .action((opts) => {
      const options: BuildOptions = {
        sourceDir: path.resolve(opts.source),
        templateDir: path.resolve(opts.templates),
        outputDir: path.resolve(opts.output),
        config: {
          title: opts.title,
          description: opts.description,
          url: opts.url,
          author: opts.author,
        },
      };

      const count = build(options);
      console.log(`Built ${count} pages.`);

      if (opts.serve) {
        const port = parseInt(opts.port, 10);
        const { wss } = startDevServer(options.outputDir, port, () => {});

        const watcher = chokidar.watch(
          [options.sourceDir, options.templateDir],
          { ignoreInitial: true }
        );
        watcher.on("all", () => {
          console.log("Change detected, rebuilding...");
          build(options);
          reloadClients(wss);
        });

        process.on("SIGINT", () => {
          watcher.close();
          wss.close();
          process.exit(0);
        });
      }
    });

  program.parse(args);
}

#!/usr/bin/env node
import { runCli } from "./cli";

runCli(process.argv);

